var getMember_createServerFn_handler = createServerRpc({
	id: "8eb65d666e9657095707b1cd8c9ca774730508361c1d2b08ea9ab2068ca443dc",
	name: "getMember",
	filename: "src/lib/library.functions.ts"
}, (opts) => getMember.__executeServer(opts));
var getMember = createServerFn({ method: "GET" }).validator((input) => ({ id: clip(input?.id, 20).toUpperCase() })).handler(getMember_createServerFn_handler, async ({ data }) => {
	if (!data.id) return { found: false };
	const sql = await getSql();
	const [member] = await sql`
      select id, name, joined_on from members where id = ${data.id}
    `;
	if (!member) return { found: false };
	const history = (await sql`
        select id, copy_id, member_id, member_name, title_id, title, author, category, shelf,
               issued_on, due_on, returned_on, is_open, is_overdue, days_past_due, chargeable_days, fine, paid
        from loan_accounts where member_id = ${data.id}
        order by issued_on desc, id desc
      `).map(mapLoan);
	const suggestions = await sql`
      select t.id, t.title, t.author, t.category
      from titles t
      where t.category in (
        select t2.category
        from loans l
        join copies c on c.id = l.copy_id
        join titles t2 on t2.id = c.title_id
        where l.member_id = ${data.id}
        group by t2.category
        order by count(*) desc
        limit 2
      )
      and not exists (
        select 1 from loans l
        join copies c on c.id = l.copy_id
        where l.member_id = ${data.id} and c.title_id = t.id
      )
      and exists (
        select 1 from copy_status cs where cs.title_id = t.id and cs.status = 'available'
      )
      order by t.title
      limit 4
    `;
	return {
		found: true,
		member: {
			id: text(member.id),
			name: text(member.name),
			joinedOn: day(member.joined_on) ?? ""
		},
		history,
		suggestions: suggestions.map((row) => ({
			id: int(row.id),
			title: text(row.title),
			author: text(row.author),
			category: text(row.category),
			reason: "Matches subjects this card already borrows, and a copy is in"
		}))
	};
});
